insert into public.regions ("id","name","description","rarity","sort_order","image_path","requires_map_fragment") values
('bluegrove','푸른골 해역','맑은 청록빛 바다 아래로 푸른 골짜기가 이어져요. 완만한 암반 사이에서 새로운 물길을 따라 낚시해 보세요.','common',3,'bluegrove.png',true),
('cloudferry','지브리의 구름나루','낮은 구름 사이로 초록 섬과 작은 나루가 이어져요. 먼 물가의 붉은 목욕탕과 언덕 위 움직이는 성을 바라보며 낚시해 보세요.','common',9,'cloudferry.png',true),
('coral','산호빛 여울','파스텔빛 산호 사이로 빠른 물살이 흘러요. 날쌘 물고기들이 여울 속에 숨어 있어요.','common',2,'coral.png',true),
('dreamabyss','꿈먹는 심연','보랏빛 물결이 어둠 속으로 이어져요. 바다 깊이 감춰진 신비가 기다리고 있어요.','epic',8,'dreamabyss.png',true),
('mistmoon','안개달 해역','은빛 안개와 달빛이 겹치는 고요한 해역. 물결 너머 낯선 움직임이 느껴져요.','rare',4,'mistmoon.png',true),
('pongdang','퐁당섬 앞바다','햇살이 부서지는 잔잔한 바다. 작은 물고기들과 첫 낚시를 시작하는 곳이에요.','common',1,'pongdang.png',false),
('primal','태고의 원시섬','거대한 고사리와 화산 안개 너머, 공룡 시대의 바다가 숨 쉬는 섬.','epic',7,'primal.png',true),
('scrapisle','녹빛 고물섬','녹슨 배와 떠밀려온 물건들이 작은 섬을 이뤘어요. 고철 사이로 자란 해초와 잊힌 보물을 찾아보세요.','common',10,'scrapisle.png',true),
('starruins','별잠 유적','별빛을 품은 오래된 유적. 잠든 바다의 기억과 희귀한 생명이 머물러요.','rare',6,'starruins.png',true),
('whitenight','백야의 빙해','해가 지지 않는 옅은 금빛 하늘 아래, 푸른 빙벽과 유빙 사이로 맑은 물길이 이어져요.','common',5,'whitenight.png',true)
