insert into public.fishing_baits ("id","name","description","price","image_path","sort_order","common_bp","rare_bp","epic_bp","mythic_bp","failure_bp","effect_kind","effect_description") values
('bait','퐁당 지렁이','퐁당섬의 촉촉한 모래와 풀숲에서만 서식하는 선홍빛 지렁이. 물속에서도 꼬물꼬물 움직여 물고기의 호기심을 자극한다. 매우 흔하고 구하기 쉬워, 섬의 초보 낚시꾼들이 가장 먼저 챙기는 미끼다.',30,'/items/baits/pongdang-worm.png',1,7700,2000,270,30,0,'fish','미끼별 등급 확률은 모든 해역에서 같아요. 주 서식지에서는 개체의 추첨 가중치가 높아져요.'),
('bait_epic','별잠의 유혹','별잠 유적의 틈에 맺힌 별가루를 자수정 조각에 봉인한 미끼. 물결에 닿으면 보랏빛 잔광이 길게 번져, 깊은 바다에 몸을 숨긴 비범한 생명까지 잠에서 깨운다고 전해진다.',null,'/items/baits/starlit-allure.png',5,0,0,9970,30,0,'fish','미끼별 등급 확률은 모든 해역에서 같아요. 주 서식지에서는 개체의 추첨 가중치가 높아져요.'),
('bait_first_greeting','소라의 첫인사','진주빛 소라에 맺힌 민트색 물방울. 아직 도감에 기록하지 못한 새로운 만남을 이끌어요.',null,'/items/baits/conch-first-greeting.png',9,7700,2000,270,30,0,'fish','낚시 성공 시 미발견 개체 확정 · 모두 발견했으면 소모되지 않아요.'),
('bait_forbidden_star','금단의 별사탕','보랏빛 별사탕의 금빛 균열에서 달콤한 별가루가 흘러나와 깊은 바다의 특별한 생물을 불러 모아요.',180,'/items/baits/forbidden-star-candy.png',6,7223,1876,760,141,0,'fish','특급·신화 추첨 가중치 증가 · 게이지 난도는 그대로예요.'),
('bait_grubby_magnet','꼬질 자석경단','해초와 작은 자석을 꾹꾹 뭉친 꼬질한 경단. 물고기 대신 바닷속 버려진 물건들이 달라붙어요.',90,'/items/baits/grubby-magnet-dumpling.png',7,7700,2000,270,30,0,'fish','낚시 성공 시 쓰레기 확정.'),
('bait_magnet','심해 인력석','깊은 해구에서 건져 올린 푸른 자철석을 다듬어 만든 인양용 미끼. 물고기 대신 바다 아래 잠든 장식물에 반응하며, 오래전에 가라앉은 보물의 흔적을 조용히 끌어당긴다.',null,'/items/baits/abyss-lodestone.png',4,0,0,0,10000,0,'decoration','모든 해역의 장식물을 만날 수 있어요. 주 서식지에서는 추첨 가중치가 높아져요.'),
('bait_safe','이슬잎 경단','새벽 이슬을 머금은 어린 잎에 향긋한 해초 반죽을 감싼 수제 미끼. 작은 쇠바늘에 단단히 붙어 쉽게 흩어지지 않고, 잎 사이로 퍼지는 순한 향이 경계심 많은 물고기를 안심시킨다.',null,'/items/baits/dewleaf-dumpling.png',3,7700,2000,270,30,0,'fish','미끼별 등급 확률은 모든 해역에서 같아요. 주 서식지에서는 개체의 추첨 가중치가 높아져요.'),
('bait_sea_memory','바다기억 조개알','파도 무늬 조개에 담긴 푸른 진주알. 지금 머무는 바다의 친구들이 기억하는 향기를 내요.',120,'/items/baits/sea-memory-clam-pearl.png',8,7700,2000,270,30,0,'fish','현재 해역 고유종 추첨 가중치 추가 3배 · 등급 확률은 그대로예요.'),
('bait_special','달빛 진주새우','달빛이 스며드는 얕은 바다에서 자라는 작은 진주새우. 반투명한 껍질 속 푸른 진주가 은은하게 빛나며, 평범한 먹이에는 다가오지 않던 진귀한 물고기까지 불러 모은다고 한다.',null,'/items/baits/special.png',2,0,9870,100,30,0,'fish','미끼별 등급 확률은 모든 해역에서 같아요. 주 서식지에서는 개체의 추첨 가중치가 높아져요.')
insert into public.collectible_species ("id","kind","name","description","swim_y_min","swim_y_max","speed","size","rarity","thumbnail_path","sell_price","sprite_sheet_path","native_region_id","movement_type","flip_with_direction","travel_direction") values
('amber-bearing-root','decoration','호박 품은 나무뿌리','구부러진 나무뿌리 안에 호박빛 수지가 고여 있다.',null,null,'0',105,'common','decorations/normal/amber-bearing-root_thumbnail.png',16,null,'primal','fixed',false,'both'),
('amber-lantern-snail','fish','호박등불 고둥','호박빛 껍데기 안에 작은 등불을 품은 고둥. 살구색 발바닥으로 앞유리에 붙어 바다의 저녁을 따뜻하게 밝힌다.','0.18','0.78','0.001',84,'rare','fish/rare/amber-lantern-snail_thumbnail.png',200,'fish/rare/amber-lantern-snail_sprite.png',null,'fixed',false,'both'),
('amethyst-cluster','decoration','자수정 군락','검은 암석 틈에서 맑은 보랏빛 결정들이 비스듬히 자란 군락.',null,null,'0',80,'rare','decorations/rare/amethyst-cluster_thumbnail.png',140,null,'dreamabyss','fixed',false,'both'),
('amethyst-fangtooth','fish','자수정 송곳니고기','자수정처럼 맑은 송곳니와 짙은 보라색 비늘을 가진 심해어.','0.2','0.8','0.025',100,'rare','fish/rare/amethyst-fangtooth_thumbnail.png',230,'fish/rare/amethyst-fangtooth_sprite.png','dreamabyss','swim',true,'both'),
('amethyst-goblin-shark','fish','자수정 마귀상어','긴 주둥이와 자수정빛 지느러미로 심연을 가르는 마귀상어.','0.2','0.8','0.025',150,'epic','fish/epic/amethyst-goblin-shark_thumbnail.png',650,'fish/epic/amethyst-goblin-shark_sprite.png','dreamabyss','swim',true,'both'),
('ammonite-fossil-slab','decoration','암모나이트 화석 판석','납작한 사암에 암모나이트의 나선 흔적이 남아 있다.',null,null,'0',95,'common','decorations/normal/ammonite-fossil-slab_thumbnail.png',14,null,'primal','fixed',false,'both'),
('anchor-chain-rock','decoration','닻줄 감긴 바위','굵은 닻 쇠사슬이 감긴 둥근 바위. 작은 해초가 푸른골 물길에 흔들린다.',null,null,'0',100,'common','decorations/normal/anchor-chain-rock_thumbnail.png',12,null,'bluegrove','fixed',false,'both'),
('ancient-coral-pillar','decoration','고대 산호 기둥','오래된 산호 골격이 켜켜이 쌓여 기둥이 되었다.',null,null,'0',145,'rare','decorations/rare/ancient-coral-pillar_thumbnail.png',165,null,'primal','fixed',false,'both'),
('apricot-starfish','decoration','살구 불가사리','통통한 다섯 팔을 펼친 살구색 불가사리. 수조 벽에 착 붙어 느긋하게 바다를 구경한다.',null,null,'0',52,'common','decorations/normal/apricot-starfish_thumbnail.png',35,null,null,'fixed',false,'both'),
('atlantean-sentinel','fish','아틀란티스 수호병','대리석 갑주와 청동 관절로 만들어진 고대 수호병. 삼지창을 들고 제자리에 서서 잠든 왕국을 지킨다. 물살에 망토가 흔들리고 갑옷 문양에 청록빛이 흐른다.','0.84','0.94','0.012',150,'mythic','fish/mythic/atlantean-sentinel_thumbnail.png',1950,'fish/mythic/atlantean-sentinel-standing_sprite.png','starruins','fixed',false,'both'),
('aurora-eel','fish','오로라장어','길게 휘어진 몸 안으로 분홍빛과 보랏빛 오로라가 흐른다. 겹겹의 지느러미를 펼칠 때마다 은빛 비늘이 별처럼 빛난다.','0.18','0.8','0.045',102,'epic','fish/epic/aurora-eel_thumbnail.png',700,'fish/epic/aurora-eel_sprite.png',null,'swim',true,'both'),
('bean-pufferfish','fish','콩알 복어','작은 콩처럼 동그란 몸에 짧은 가시가 돋아 있다. 노란 지느러미를 파닥이며 바다 친구들 사이를 오간다.','0.18','0.8','0.045',52,'common','fish/normal/bean-pufferfish_thumbnail.png',35,'fish/normal/bean-pufferfish_sprite.png',null,'swim',true,'both'),
('billowmouth-leedsichthys','fish','너울입 리즈시크티스','넓은 입으로 작은 먹이를 걸러 먹는 온순한 거대 물고기.','0.18','0.8','0.018',160,'common','fish/normal/billowmouth-leedsichthys_thumbnail.png',35,'fish/normal/billowmouth-leedsichthys_sprite.png','primal','swim',true,'both'),
('billowsail-sailfish','fish','돛너울 돛새치','청록색 돛지느러미가 물결처럼 펼쳐지는 날렵한 돛새치.','0.18','0.8','0.035',144,'rare','fish/rare/billowsail-sailfish_thumbnail.png',210,'fish/rare/billowsail-sailfish_sprite.png',null,'swim',true,'both'),
('blackscale-mosasaurus','fish','흑청비늘 모사사우루스','흑청빛 비늘과 강한 꼬리로 태고의 깊은 바다를 가른다.','0.18','0.8','0.018',178,'epic','fish/epic/blackscale-mosasaurus_thumbnail.png',660,'fish/epic/blackscale-mosasaurus_sprite.png','primal','swim',true,'both'),
('blue-bronze-horseshoe-crab','fish','청금 투구게','오래된 청동을 닮은 등껍질 가장자리에 푸른빛이 돈다. 가느다란 꼬리를 끌며 바닥의 오래된 길을 더듬는다.','0.86','0.95','0.022',66,'rare','fish/rare/blue-bronze-horseshoe-crab_thumbnail.png',170,'fish/rare/blue-bronze-horseshoe-crab_sprite.png',null,'crawl',false,'both'),
('blue-great-white','fish','푸른 백상아리','묵직한 몸과 뾰족한 등지느러미를 가진 상어. 푸른 회색 등 아래 크림빛 배가 드러나고, 작은 이빨 사이로 장난스러운 미소가 보인다.','0.15','0.80','0.055',136,'rare','fish/rare/blue-great-white_thumbnail.png',380,'fish/rare/blue-great-white_sprite.png',null,'swim',true,'both'),
('blue-ice-crystal','decoration','푸른 얼음 수정','투명한 푸른 결정이 바닥에서 낮게 솟아 있다.',null,null,'0',108,'common','decorations/normal/blue-ice-crystal_thumbnail.png',18,null,'whitenight','fixed',false,'both'),
('blue-sailfish','fish','푸른 돛새치','긴 주둥이와 커다란 돛 모양 등지느러미를 가진 물고기. 푸른 몸을 펼치며 바닷속을 시원하게 가로지른다.','0.20','0.70','0.065',112,'common','fish/rare/blue-sailfish_thumbnail.png',220,'fish/rare/blue-sailfish_sprite.png',null,'swim',true,'both'),
('blue-scaled-mahi-mahi','fish','푸른비늘 만새기','높은 이마와 길게 이어진 등지느러미, 청금빛 비늘을 가진 만새기.','0.18','0.8','0.025',145,'epic','fish/epic/blue-scaled-mahi-mahi_thumbnail.png',560,'fish/epic/blue-scaled-mahi-mahi_sprite.png','bluegrove','swim',true,'both'),
('blue-spotted-leopard-shark','fish','푸른점 표범상어','유려한 긴 몸에 푸른 점무늬가 흐르는 푸른골의 표범상어.','0.18','0.8','0.025',156,'epic','fish/epic/blue-spotted-leopard-shark_thumbnail.png',590,'fish/epic/blue-spotted-leopard-shark_sprite.png','bluegrove','swim',true,'both'),
('blueback-shonisaurus','fish','푸른등 쇼니사우루스','푸른 등과 넓은 몸통을 지닌 거인이 느긋하게 헤엄친다.','0.18','0.8','0.018',180,'epic','fish/epic/blueback-shonisaurus_thumbnail.png',650,'fish/epic/blueback-shonisaurus_sprite.png','primal','swim',true,'both'),
('blueback-spanish-mackerel','fish','푸른등 삼치','푸른 등과 길쭉한 은빛 몸을 가진 삼치.','0.18','0.8','0.035',108,'common','fish/normal/blueback-spanish-mackerel_thumbnail.png',28,'fish/normal/blueback-spanish-mackerel_sprite.png','bluegrove','swim',true,'both'),
('bluegrain-scallop','fish','푸른결 가리비','얼음 결정 같은 푸른 결이 부채 모양 껍데기에 새겨져 있다.','0.84','0.94','0.012',84,'common','fish/normal/bluegrain-scallop_thumbnail.png',24,'fish/normal/bluegrain-scallop_sprite.png','whitenight','fixed',false,'both'),
('bluegrove-giant-seabass','fish','푸른골 대왕농어','푸른골 암반색의 청록 반점과 커다란 입을 가진 토착 대왕농어.','0.18','0.8','0.025',154,'rare','fish/rare/bluegrove-giant-seabass_thumbnail.png',240,'fish/rare/bluegrove-giant-seabass_sprite.png','bluegrove','swim',true,'both'),
('bluegrove-spearfish','fish','푸른창 청새치','푸른골 물길을 따라 긴 창 같은 주둥이로 나아가는 청새치.','0.18','0.8','0.025',145,'rare','fish/rare/bluegrove-spearfish_thumbnail.png',225,'fish/rare/bluegrove-spearfish_sprite.png','bluegrove','swim',true,'both'),
